import Foundation
struct DiscoverySite {
 let place:Place
 let region:String
 let fact:String
 let hint:String
 let source:String
 init(_ name:String,_ lat:Float,_ lon:Float,_ alt:Float,_ region:String,_ fact:String,_ hint:String,_ source:String){place=Place(name:name,lat:lat,lon:lon,alt:alt);self.region=region;self.fact=fact;self.hint=hint;self.source=source}
}
// Stable order: the original 16 IDs remain intact when the passport grows.
let discoverySites:[DiscoverySite] = [
 .init("Golden Gate Bridge",37.8199,-122.4783,180,"THE GOLDEN GATE","That famous color is International Orange. The bridge connects San Francisco to Marin across the narrow entrance between the Pacific and the bay.","Follow the orange towers north from the Presidio.","https://www.goldengate.org/bridge/history-research/"),
 .init("Alcatraz",37.8267,-122.423,160,"ISLAND HOPPING","A fortress, a prison, and a place of Native American activism: this small island has many layers of history. Its cellhouse and lighthouse make an unmistakable silhouette.","Look for the rocky island between the city and Angel Island.","https://www.nps.gov/alca/learn/historyculture/index.htm"),
 .init("Coit Tower",37.8024,-122.4058,220,"SAN FRANCISCO","The pale tower on Telegraph Hill has watched over the waterfront since 1933. Inside, murals tell stories of California life during the Depression.","Find the white column on the hill above the northeast waterfront.","https://www.sfrecpark.org/684/Points-of-Interest"),
 .init("Transamerica Pyramid",37.7952,-122.4028,300,"SAN FRANCISCO","A sharp point among the city’s flat rooftops! The Transamerica Pyramid is one of San Francisco’s most recognizable buildings, with a grove of redwoods at its base.","Search for the pointed tower south of Coit Tower.","https://www.thepyramid.com/"),
 .init("Salesforce Tower",37.7897,-122.3966,380,"SAN FRANCISCO","The rounded crown belongs to San Francisco’s tallest tower. Nearby, Salesforce Park is an elevated garden stretching across the roof of the transit center.","Climb above the tallest rounded tower in the downtown skyline.","https://salesforcetransitcenter.com/salesforce-park/"),
 .init("Palace of Fine Arts",37.8029,-122.4484,150,"SAN FRANCISCO","This rotunda began as part of the 1915 Panama-Pacific exhibition. Its classical columns and lagoon make a surprisingly quiet corner of the Marina.","Look just inland from the waterfront, east of the Presidio.","https://www.sfrecpark.org/684/Points-of-Interest"),
 .init("Golden Gate Park",37.7694,-122.4862,220,"SAN FRANCISCO","A huge green rectangle reaches almost to the ocean. Golden Gate Park holds gardens, lakes, museums, and winding paths inside the city’s street grid.","Follow the long green park west toward the Pacific.","https://www.sfrecpark.org/684/Points-of-Interest"),
 .init("Twin Peaks",37.7544,-122.4477,430,"SAN FRANCISCO","Two neighboring summits rise above the center of San Francisco. From here the street grid fans out toward downtown, the bay, and the Pacific.","Climb over the two bare hills south of Golden Gate Park.","https://sfrecpark.org/Facilities/Facility/Details/Twin-Peaks-384"),
 .init("Bay Bridge",37.798,-122.377,200,"ACROSS THE BAY","This crossing is really a sequence of bridges joined at Yerba Buena Island. The western suspension spans and the eastern span have distinctly different shapes.","Fly east from the downtown waterfront toward Yerba Buena Island.","https://www.bayareafastrak.org/en/bridges/san-francisco-oakland-bridge.shtml"),
 .init("Sausalito",37.859,-122.485,180,"MARIN","Hillside homes face a sheltered waterfront in this Marin town. The bay is calmer here than at the ocean-facing cliffs just over the ridge.","Follow the Marin shoreline north from the Golden Gate.","https://www.discoversausalito.com/"),
 .init("Mount Tamalpais",37.9235,-122.5965,900,"MARIN","Mount Tam rises above Marin’s ridges and forests. On clear days, its high slopes reveal the bay on one side and the Pacific on the other.","Head northwest and climb toward Marin’s tallest ridge.","https://www.parks.ca.gov/?page_id=471"),
 .init("Oakland",37.8044,-122.2712,240,"EAST BAY","Oakland’s waterfront, downtown, and hillside neighborhoods share the sunny side of the bay. The port’s container cranes stand along the western shoreline.","Cross the Bay Bridge and continue southeast toward downtown Oakland.","https://www.visitoakland.com/"),
 .init("Berkeley",37.8715,-122.273,260,"EAST BAY","From the waterfront, Berkeley climbs toward its university campus and the East Bay hills. Its rectangular street grid is easy to trace from above.","Follow the East Bay shoreline north from Oakland.","https://www.visitberkeley.com/"),
 .init("San Francisco Airport",37.6213,-122.379,200,"THE PENINSULA","SFO’s long runways project into the bay. From the air, the runway pairs and their surrounding taxiways form a distinctive geometric pattern.","Look along the eastern Peninsula shoreline, south of the city.","https://www.flysfo.com/"),
 .init("San Mateo Bridge",37.596,-122.25,180,"SOUTH BAY","A long, low causeway links the Peninsula with the East Bay. Compared with the Golden Gate, much of this crossing sits close to the water.","Look southeast of SFO for the long crossing over open water.","https://www.bayareafastrak.org/en/bridges/san-mateo-hayward-bridge.shtml"),
 .init("Angel Island",37.86,-122.432,420,"ISLAND HOPPING","This island is a state park with a complicated past. Its immigration station processed and detained immigrants, particularly from Asia; preserved buildings tell their stories.","Climb over the large hilly island north of Alcatraz.","https://www.parks.ca.gov/?page_id=1309"),
 .init("Crissy Field",37.803,-122.466,140,"THE GOLDEN GATE","Before it became a waterfront park, Crissy Field was an Army airfield. A fitting place for a little sightseeing flight to begin!​","Find the open shoreline on the city side of the Golden Gate.","https://www.nps.gov/prsf/learn/historyculture/crissy-field.htm"),
 .init("Ferry Building",37.7955,-122.3937,160,"SAN FRANCISCO","The waterfront clock tower marks the foot of Market Street. Ferries still connect this landmark with communities around the bay.","Follow the downtown shoreline to the clock tower.","https://www.ferrybuildingmarketplace.com/"),
 .init("City Hall",37.7793,-122.4192,220,"SAN FRANCISCO","A grand dome crowns San Francisco’s Civic Center. Its broad courtyards and formal street layout stand out from the surrounding neighborhoods.","Look southwest of downtown for the large civic dome.","https://www.sf.gov/location/san-francisco-city-hall"),
 .init("Sutro Tower",37.7552,-122.4528,670,"SAN FRANCISCO","Three tall legs and red-and-white antenna masts make Sutro Tower a local landmark. It helps broadcast television and radio across the region.","Climb west of Twin Peaks toward the three-legged tower.","https://sutrotower.com/"),
 .init("Ocean Beach",37.759,-122.510,140,"PACIFIC COAST","The city ends in a long sweep of sand facing the Pacific. This open coast is a very different world from the sheltered water inside the bay.","Follow the western edge of San Francisco south from the park.","https://www.nps.gov/goga/planyourvisit/oceanbeach.htm"),
 .init("Lands End",37.782,-122.506,200,"PACIFIC COAST","Rocky bluffs turn from the ocean toward the Golden Gate. Coastal trails here wind past cypress trees, headlands, and views of the bridge.","Follow the coast around San Francisco’s northwest corner.","https://www.nps.gov/goga/planyourvisit/landsend.htm"),
 .init("Oracle Park",37.7786,-122.3893,180,"SAN FRANCISCO","The Giants’ ballpark sits right against the water. Beyond the right-field wall, McCovey Cove is famous for boats waiting for splash-hit home runs.","Look for the waterfront baseball diamond south of the Bay Bridge.","https://www.mlb.com/giants/ballpark"),
 .init("Presidio",37.798,-122.455,210,"THE GOLDEN GATE","Once a military post, the Presidio is now part of the national park landscape. Forest, historic buildings, and open spaces fill the city’s northwest corner.","Explore the wooded land behind Crissy Field.","https://presidio.gov/about/history")
]
let sights=discoverySites.map(\.place)
